package com.autoops.files.entity;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="stored_files")public class StoredFile{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="original_filename",nullable=false)private String originalFilename;@Column(name="object_key",nullable=false,unique=true)private String objectKey;@Column(nullable=false)private Long size;@Column(nullable=false)private String checksum;@Column(name="created_by",nullable=false)private Long createdBy;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();@Column(name="orphaned_at")private Instant orphanedAt;public Long getId(){return id;}public String getObjectKey(){return objectKey;}public void setOriginalFilename(String v){originalFilename=v;}public void setObjectKey(String v){objectKey=v;}public void setSize(Long v){size=v;}public void setChecksum(String v){checksum=v;}public void setCreatedBy(Long v){createdBy=v;}}
